/// <summary>
/// MPJ_24248 Pricing Data Extract
/// Common methods related to RetailPeriodicDiscount
/// </summary>
abstract class METPriceChangeTrackPriceAdjEnabled extends METPriceChangeTrack
{
}

Method.Source:
    /// <summary>
    /// Process the Change tracking record and create a Price data feed record
    /// </summary>
    public void process()
    {
        RetailPeriodicDiscountLine  retailPeriodicDiscountLine;
        Query               custPreviewQuery;
        Query               productPreviewQuery;
        GUPPricingRuleCopy  pricingRuleCopyCustHeader, pricingRuleCopy;
        InventDim           inventDim;
        Set                 custAccountSet, inventItemSet;
        GUPGroupAll         discountTableGroup;
        str                 message;

        priceDataFeedCount = 0;
        priceDataFeedList = this.createPriceDataFeedList();

        discountTableGroup = RetailPeriodicDiscount::find(priceChangeTrackingOrig.RefRecId).HeaderPricingGroupCode;

        pricingRuleCopyCustHeader.initFromPricingRule(GUPPricingRule::find(priceChangeTrackingOrig.pricingRuleHeader));
        
        while select OfferId, LinePricingRule, UnitOfMeasure, InventDimId, LineNum
            from    retailPeriodicDiscountLine
            where   retailPeriodicDiscountLine.OfferId == this.getChangeCode(priceChangeTrackingOrig)
            outer join InventSiteId
            from    InventDim
            where   InventDim.InventDimId               == retailPeriodicDiscountLine.InventDimId
        {
            pricingRuleCopy.initFromPricingRule(GUPPricingRule::find(retailPeriodicDiscountLine.LinePricingRule));

            custPreviewQuery = this.buildCustQuery(pricingRuleCopyCustHeader, InventDim.InventSiteId, discountTableGroup);
            custAccountSet = this.buildCustValues(custPreviewQuery, pricingRuleCopyCustHeader);
            
            if(custAccountSet)
            {
                productPreviewQuery = this.buildProductQueryBase(pricingRuleCopy);
                inventItemSet = this.buildItemValues(productPreviewQuery, pricingRuleCopy);

                if(inventItemSet)
                {
                    this.processMulti(custAccountSet, 
                                        inventItemSet, 
                                        InventDim.InventSiteId,
                                        this.getUOMSymbolFromId(retailPeriodicDiscountLine.UnitOfMeasure), 
                                        retailPeriodicDiscountLine.LineNum);
                }
                else
                {
                    if(showValidation)
                    {
                        this.logMessage(strFmt('No products selected for processing\n'));
                    }
                }
            }
            else
            {
                if(showValidation)
                {
                    this.logMessage(strFmt('No customers selected for processing\n'));
                }
            }
        }

        if(priceDataFeedCount)
        {
            ttsbegin;
            priceDataFeedList.insertDatabase();
            ttscommit;
        }
    }

/// <summary>
/// Create a Price data feed record
/// </summary>
/// <param name = "_priceChangeTrackingUpdate">Price change tracking</param>
/// <param name = "_lineNumber">Line number</param>
/// <param name = "_eventId">Event ID</param>
public void createPriceDataFeedAll(METPriceChangeTracking           _priceChangeTrackingUpdate,
                                    LineNumber                      _lineNumber,
                                    METEventId                      _eventId)
{
    super(_priceChangeTrackingUpdate, _lineNumber, _eventId);
    this.createPriceDataFeedExpire(this.getExpiryCreationType(), _priceChangeTrackingUpdate, _lineNumber, _eventId, METConstants::emptyString, 0);
}

/// <summary>
/// get expiry creation type
/// </summary>
/// <returns>creation type</returns>
abstract METCreationType getExpiryCreationType()
{
}
